"""Rebuild the curated evidence database from the archived CSVs and curated constants.
Python >=3.9; standard library only. Does not execute a simulation or fit any parameter.
"""
from pathlib import Path
import csv, sqlite3, json, hashlib, datetime, collections
ROOT=Path(__file__).resolve().parents[1]; O=ROOT/'original'; E=ROOT/'data'; E.mkdir(exist_ok=True)
DB=ROOT/'RhizoField_evidence.sqlite'; DB.unlink(missing_ok=True)
c=sqlite3.connect(DB); c.execute('PRAGMA foreign_keys=ON'); c.executescript('''
CREATE TABLE sources (source_id TEXT PRIMARY KEY, topic TEXT NOT NULL, citation TEXT NOT NULL, doi TEXT UNIQUE NOT NULL, source_url TEXT NOT NULL, provenance TEXT NOT NULL, material_or_protocol TEXT NOT NULL, intended_use TEXT NOT NULL, qualification TEXT NOT NULL);
CREATE TABLE observations (observation_id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources NOT NULL, specimen_group TEXT NOT NULL, observable TEXT NOT NULL, value REAL, unit TEXT NOT NULL, qualifier TEXT NOT NULL, uncertainty REAL, uncertainty_type TEXT, evidence_type TEXT NOT NULL, use_role TEXT NOT NULL, protocol TEXT NOT NULL, locator TEXT NOT NULL, source_url TEXT NOT NULL, provenance TEXT NOT NULL, CHECK((value IS NULL AND qualifier='missing') OR (value IS NOT NULL AND qualifier IN ('=','~','<','>'))), CHECK(uncertainty IS NULL OR uncertainty>=0));
CREATE TABLE shear_specimens (specimen TEXT PRIMARY KEY, source_id TEXT REFERENCES sources NOT NULL, material TEXT, density_Mg_m3 REAL NOT NULL, suction_op TEXT, suction_kPa REAL, water_op TEXT, water_g_g_from_SWRC REAL, root_area_ratio_pct REAL, experiment_mode TEXT, note TEXT, source_url TEXT NOT NULL);
CREATE TABLE resources (asset_id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources NOT NULL, asset TEXT NOT NULL, locator_url TEXT NOT NULL, access_status TEXT NOT NULL, data_format TEXT, size_or_checksum TEXT, use_and_limits TEXT NOT NULL);
CREATE TABLE tests (test_id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources NOT NULL, component TEXT, use_role TEXT, input_and_split TEXT, observable_or_metric TEXT, readiness TEXT, exclusion_or_gate TEXT, source_url TEXT NOT NULL);
CREATE TABLE settings (name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX role_idx ON observations(use_role,source_id); CREATE INDEX spec_idx ON observations(specimen_group);
''')
base='https://doi.org/'
lookup={}
def s(i,topic,cit,doi,prov,material,use,lim):
    url=base+doi;lookup[i]=url;c.execute('INSERT INTO sources VALUES(?,?,?,?,?,?,?,?,?)',(i,topic,cit,doi,url,prov,material,use,lim))
s('KOH05','Root hydraulics','Köhne (2005) · Mini suction cups and water extraction','10.2136/vzj2004.0111','Baseline CSV','Porous small/large ceramic cups in soil; varied saturation and vacuum.','Apparent system uptake; reserve large saturated cup.','Effective cup and soil resistance; not intrinsic woody membrane permeability.')
s('LEU03','Root hydraulics','Leuschner et al. (2003) · Periderm and in situ fine-root water absorption','10.1051/forest:2003071','Baseline CSV','Beech, oak, spruce; single stand, four dates.','Species-specific field prior; hold out last date.','Dates or roots from one stand are not independent sites; group dispersion is SD.')
s('CUN18','Root hydraulics / wetting','Cuneo et al. (2018) · Water uptake through woody grapevine roots','10.1111/nph.15032','Baseline CSV + primary article','Intact and peeled grapevine root; prior hydration; hydrostatic uptake.','Treatment-specific uptake inputs and an advancing-angle constraint.','Advancing bark angle ≠ receding angle; area basis differs from wetted area.')
s('HUE22','Capillarity','Hueckel et al. (2022) · Dynamics and instabilities of Haines jumps','10.1029/2022WR033246','Baseline CSV + source notes','Three borosilicate cylinders; water; measured apparent angles.','Two-site glass calibration with within-run checks.','No independent replicate from four contact sites; three-body force is not a two-body force.')
s('LIA26','Capillarity','Liao et al. (2026) · Wetting morphology and capillary force between parallel cylinders','10.1002/aic.70229','Consensus Pro + publisher; previously listed, not ingested','Parallel cylinders of varying diameters, gap, volume and wettability.','Reserve measured force–gap series and bridge geometry.','The supplement mixes measurements, Surface Evolver and analytical curves. Total N ≠ N/m.')
s('CHE26','Wetting','Chen & Arye (2026) · Liquid and dried maize root mucilage','10.1016/j.rhisph.2026.101423','Consensus Pro + primary article','Dried maize mucilage coatings and liquid formulations on planar substrate.','Conditional bounds for coated-substrate sensitivity.','Neither a receding bark angle nor a measured total water–air tension. Do not use as bare-root constants.')
s('WAN16','Capillarity','Wang et al. (2016) · Capillary force and rupture of funicular liquid bridges','10.1016/j.powtec.2016.09.060','Consensus Pro + publisher','Multiple particles / connected liquid; boundary condition matters.','Future topology and rupture test.','Separate experiment from simulated suction-controlled cases; match topology and protocol.')
s('BOK26','Capillarity','Bokányi-Tóth et al. (2026) · Liquid bridges between horizontal cylinders','10.1017/jfm.2026.12035','Consensus Pro + publisher','Horizontal rods; oils; morphology and dynamics.','Geometry and relaxation comparator.','Not water or biological uptake; transient validation needs a dynamic solver.')
s('BAC24','Root hydraulics','Baca Cabrera et al. (2024) · Root hydraulic properties database','10.1002/pld3.582','Primary authors’ data release and linked repository','Many species; radial, axial and whole-root-system properties.','Locate external hydrostatic radial measurements at original-study level.','Deduplicate by original study; filter tissue, area basis, driving force and units. Not independent evidence itself.')
s('KEY17','Growth / 4D CT','Keyes et al. (2017) · Measurement of soil deformation around growing root tips','10.1098/rsif.2017.0560','Existing benchmark + data record','Intact and decapped maize; synchrotron CT with DVC and grain tracking.','Soil displacement around growing roots.','Root growth moves tissue into the ROI; mask it. Not a suction field or woody pull-out.')
s('ANS21','Growth / 4D CT','Anselmucci et al. (2021) · Root–soil microstructure interaction in sand','10.1038/s41598-021-01056-1','Baseline benchmark CSV + 4TU record','Maize in fine/coarse Hostun sand; public release covers loose preparations.','Porosity versus distance; candidate grain/DVC replay.','Radial porosity extent is not the extent of displacement. Dense target is paper only in this release.')
s('HER22','Tree architecture','Herrero-Huerta et al. (2022) · Black walnut root architecture in 4D','10.3389/fpls.2022.986856','Baseline benchmark CSV','One black walnut seedling; three weekly scans.','Prescribed tree geometry or held-out growth geometry.','Not independent plants; root-only surfaces cannot provide soil displacements.')
s('IIJ03','Growth mechanics','Iijima et al. (2003) · Root cap removal and maize penetration resistance','10.1093/jxb/erg226','Primary numerical table','Intact vs decapped maize cv. Mephisto; loose/compacted soil; two experiments.','Independent future growth-force benchmark; preserve both experiments.','Macroscopic penetration resistance = measured root force / estimated root area, not suction.')
s('MCK13','Interface friction','McKenzie et al. (2013) · Root–soil friction from penetration and rotation','10.1111/pce.12037','Primary study','Growing pea roots and a slow rotating probe; adhesion assumptions varied.','Prior for an effective root-tip interface, not a grain law.','0.21 and 0.26 are alternative model estimates from the same data, not two replicates.')
s('SCH11','Pull-out / shear','Schwarz et al. (2011) · Pullout tests of root analogs and natural bundles','10.1029/2010JF001753','Primary study','Wet/dry sand and silty soil; low confining loads.','Macroscopic interface resistance bounds.','Confinement and moisture both change between quoted extrema. Values in kPa are not Coulomb coefficients.')
s('BUL20','Shear / DVC','Bull et al. (2020) · Root reinforcement in 4D CT and DVC','10.1098/rspa.2019.0838','Primary paper + authors’ open archive','Willow C under interrupted direct shear; noise controls.','Physical DVC noise threshold and withheld displacement field.','Shares Willow C with Bull 2022. No growth between these load steps is assumed.')
s('BUL22','Shear / DVC','Bull et al. (2022) · Stress transfer in root-reinforced soils','10.1098/rspa.2021.0210','Primary numerical tables + dataset record','Bullionfield soil; willow, gorse, fallow and artificial roots.','Specimen conditions, shear displacement histories, load and field comparators.','Top tensiometer is not the shear-plane suction field; water content calculated via retention curve.')
s('TOM21','Suction / shear','Tomobe et al. (2021) · Root–soil interface under changing suction','10.1016/j.sandf.2021.03.005','Primary study','Separate suction-controlled and normal-stress-controlled interface tests.','Reserve a suction series for validation after dry interface calibration.','Schedules are imposed conditions, not strength observations. Do not combine the separate series.')
s('KAM14','Anchorage','Kamchoom, Leung & Ng (2014) · Root geometry, transpiration and pull-out','10.1680/geolett.14.00086','Primary study; previously listed','Centrifuge root analogues; different geometries and transpiration.','Held-out full-root anchorage test.','Requires scale conversion, root architecture, and many-grain contact. Not a local capillary force.')
s('NG14','Root hydraulics','Ng et al. (2014) · Porous root system and transpiration-induced suction in centrifuge','10.1520/GTJ20130116','Primary study','Porous root surrogate under vacuum.','Reserve suction magnitude and profile for analogue hydraulics.','Do not substitute analogue conductance for plant tissue or count related apparatus as independent without checking.')
s('MIC07','Pull-out / deformation','Mickovski et al. (2007) · Stiffness, branching and matric potential in pull-out','10.1111/j.1365-2389.2007.00953.x','Primary study','Analogue materials; geometry and moisture effects; 2D imaging.','Force–displacement / root-shape holdouts.','Treat any replot of the same experimental curve as one observation family.')
s('MEI19','Root mechanics','Meijer et al. (2019) · Coupled axial and lateral root deformation','10.1002/nag.2880','Primary study + associated data record','Root analogues with different bending/axial stiffness; experiments and calculations.','Select empirical curves only; root deformation and force.','Fig. 20 reproduces previously published data; do not count twice with Mickovski.')
s('ZHU25','Anchorage','Zhu et al. (2025) · Australian native species: root bundle pull-out','10.1007/s11440-025-02603-0','Primary study','Field-scale tree and shrub roots; species / morphologies differ.','Order-of-magnitude external check for full-tree module.','No comparison of whole-bundle N against a 2D grain force in N/m.')
rows=[]
def obs(k,g,m,v,u,t,role,cond,loc,prov='New transcription',q='=',err=None,ut=None):
    rows.append((f'O{len(rows)+1:03}',k,g,m,v,u,q,err,ut,t,role,cond,loc,lookup[k],prov))
